static System.Random random=new System.Random(100051);static float R(float a,float b){return a+(float)random.NextDouble()*(b-a);}static Terrain ground;static Transform art;static List<string> changes=new List<string>();
static Transform Group(string n){var g=new GameObject(n);g.transform.SetParent(art,false);return g.transform;}
static GameObject Put(GameObject source,Transform parent,Vector3 p,float width,float yaw,string n,bool solid=false){var go=Object.Instantiate(source,parent);go.name=n;go.SetActive(true);go.transform.rotation=Quaternion.Euler(0,yaw,0);var b=B(go);go.transform.localScale*=width/Mathf.Max(.01f,b.size.x);b=B(go);go.transform.position+=new Vector3(p.x-b.center.x,p.y-b.min.y,p.z-b.center.z);foreach(var c in go.GetComponentsInChildren<Collider>())Object.DestroyImmediate(c);if(solid){foreach(var mf in go.GetComponentsInChildren<MeshFilter>().Where(m=>!m.name.Contains("LOD")||m.name.Contains("LOD0"))){if(mf.sharedMesh)mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}}return go;}
static Vector3 G(float x,float z,float offset=0){return new Vector3(x,ground.SampleHeight(new Vector3(x,0,z))+ground.transform.position.y+offset,z);}
static Texture2D Tex(string n){return AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/ResTemporary/BlazingHighlands/Source/Textures/"+n);}
static void Ground(){var td=Object.Instantiate(ground.terrainData);td.name="10005a_01a_Independent_Terrain";AssetDatabase.CreateAsset(td,Root+"/10005a_01a_Independent_Terrain.asset");ground.terrainData=td;var tc=ground.GetComponent<TerrainCollider>();if(tc)tc.terrainData=td;string[] files={"T_Grassy_Ground_01_BC.png","T_Ground_01_BC.png","T_Cliff_Large_01_BC.png"};var layers=new TerrainLayer[3];for(int i=0;i<3;i++){layers[i]=new TerrainLayer();layers[i].diffuseTexture=Tex(files[i]);layers[i].tileSize=new Vector2(i==2?5:6,i==2?5:6);AssetDatabase.CreateAsset(layers[i],Root+"/GroundLayer_"+i+".terrainlayer");}td.terrainLayers=layers;int res=td.alphamapResolution;var alpha=new float[res,res,3];for(int z=0;z<res;z++)for(int x=0;x<res;x++){float u=x/(float)(res-1),v=z/(float)(res-1);float wx=ground.transform.position.x+u*td.size.x,wz=ground.transform.position.z+v*td.size.z;float slope=td.GetSteepness(u,v);float cliff=Mathf.SmoothStep(0,1,Mathf.InverseLerp(27,50,slope));float path=Mathf.Exp(-Mathf.Pow(PathDistance(new Vector2(wx,wz))/1.8f,2));float dirt=Mathf.Clamp01(path*.85f+.08f)*(1-cliff);alpha[z,x,0]=(1-cliff)-dirt;alpha[z,x,1]=dirt;alpha[z,x,2]=cliff;}td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);ground.Flush();changes.Add("Ground: independent terrain and 3 BlazingHighlands terrain layers, paths retained by route painting.");}
static Vector2[] route={new Vector2(12,18),new Vector2(24,30),new Vector2(24,45),new Vector2(38,57),new Vector2(51,66),new Vector2(67,66),new Vector2(80,76),new Vector2(93,83)};static float PathDistance(Vector2 p){float best=1000;for(int i=1;i<route.Length;i++){var a=route[i-1];var d=route[i]-a;best=Mathf.Min(best,Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/d.sqrMagnitude)));}return best;}
static void Build(){var s=Load("10005a");if(All(s).Any(t=>t.name=="10005a_Extension_Of_10001a"))throw new Exception("Already built");EditorSceneManager.SaveScene(s,W+"/outputs/Extension01a/10005a_before_extension.unity",true);var reference=Load("10001a");var refs=All(reference);var cliff=refs.First(t=>t.gameObject.activeInHierarchy&&t.name.StartsWith("SM_Cliff_Large_01_B")&&!t.name.Contains("LOD")).gameObject;var grass=refs.First(t=>t.gameObject.activeInHierarchy&&t.name=="SM_Grass_01").gameObject;var old=All(s);ground=old.Select(t=>t.GetComponent<Terrain>()).First(t=>t&&t.gameObject.activeInHierarchy);var root=new GameObject("10005a_Extension_Of_10001a");SceneManager.MoveGameObjectToScene(root,s);art=root.transform;Ground();
var cliffGroup=Group("01_10001a_Grass_Topped_Cliffs");var prior=old.Where(t=>t.name.StartsWith("Reference10001_Cliff_")).ToArray();var targets=old.Where(t=>t.name=="Cave_R09_WallSegment"&&(t.gameObject.activeInHierarchy||prior.Any(p=>(p.position-t.position).sqrMagnitude<20))).ToArray();int index=0;foreach(var t in targets){var b=B(t.gameObject);var g=Put(cliff,cliffGroup,new Vector3(b.center.x,b.min.y,b.center.z),Mathf.Max(3.5f,b.size.x),R(-18,18),"01a_Cliff_"+index++,true);var nb=B(g);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(1,Mathf.Clamp(b.size.y/nb.size.y,.7f,4),Mathf.Clamp(b.size.z/nb.size.z,.65f,1.6f)));nb=B(g);g.transform.position+=new Vector3(b.center.x-nb.center.x,b.min.y-nb.min.y,b.center.z-nb.center.z);t.gameObject.SetActive(false);}foreach(var t in old.Where(t=>t.name.StartsWith("Reference10001_Cliff_")||t.name.StartsWith("Reference10001_Grass_")||t.name.StartsWith("Cliff_Foot_Grass_")))t.gameObject.SetActive(false);changes.Add("Replaced cliffs with 10001a SM_Cliff_Large_01_B: "+index);
var grassGroup=Group("02_Dense_10001a_Grass_Meadows");int grassCount=0;for(float z=2;z<98;z+=.95f)for(float x=2;x<98;x+=.95f){var p=G(x+R(-.35f,.35f),z+R(-.35f,.35f),-.04f);if(p.y>8||p.y<3.15f)continue;float u=(p.x-ground.transform.position.x)/ground.terrainData.size.x,v=(p.z-ground.transform.position.z)/ground.terrainData.size.z;if(ground.terrainData.GetSteepness(u,v)>28)continue;if(OnRiver(p,old))continue;float pd=PathDistance(new Vector2(p.x,p.z));float chance=pd<1.5f?.06f:pd<2.6f?.45f:.92f;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(80,76))<6)chance*=.12f;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(83,85))<5.8f)continue;if(R(0,1)>chance)continue;Put(grass,grassGroup,p,R(.85f,1.5f),R(0,360),"01a_Grass_"+grassCount++);}changes.Add("Dense grass patches: "+grassCount);
Shrine(old);Details(old);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllLines(W+"/outputs/Extension01a/Changes.txt",changes);Capture();SceneManager.SetActiveScene(s);}
static bool OnRiver(Vector3 p,Transform[] old){var t=old.FirstOrDefault(x=>x.name=="Replanned_Serpentine_River");if(!t)return false;var mf=t.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)return false;var verts=mf.sharedMesh.vertices;var tris=mf.sharedMesh.triangles;Vector2 pt=new Vector2(p.x,p.z);for(int i=0;i<tris.Length;i+=3){Vector3 av=t.TransformPoint(verts[tris[i]]),bv=t.TransformPoint(verts[tris[i+1]]),cv=t.TransformPoint(verts[tris[i+2]]);var a=new Vector2(av.x,av.z);var b=new Vector2(bv.x,bv.z);var c=new Vector2(cv.x,cv.z);float d1=Cross(pt-a,b-a),d2=Cross(pt-b,c-b),d3=Cross(pt-c,a-c);if((d1>=0&&d2>=0&&d3>=0)||(d1<=0&&d2<=0&&d3<=0))return true;}return false;}static float Cross(Vector2 a,Vector2 b){return a.x*b.y-a.y*b.x;}
static Dictionary<Material,Material> stoneMats=new Dictionary<Material,Material>();static void Stone(GameObject go){foreach(var r in go.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var src=mats[i];if(!src)continue;if(!stoneMats.ContainsKey(src)){var m=new Material(src);if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",new Color(.62f,.69f,.59f));if(m.HasProperty("_Color"))m.SetColor("_Color",new Color(.62f,.69f,.59f));AssetDatabase.CreateAsset(m,Root+"/RuinStone_"+stoneMats.Count+".mat");stoneMats[src]=m;}mats[i]=stoneMats[src];}r.sharedMaterials=mats;}}
static void Shrine(Transform[] old){var group=Group("03_Carved_Fountain_And_Natural_Spring");foreach(var t in old.Where(t=>t.name=="Ancient_Spring_Stonework"||t.name=="Spring_Inset_Basin_Water"||t.name=="Spring_Cascade"))t.gameObject.SetActive(false);var fountain=Put(Lib("TFD_Fountain_01A"),group,G(83,87),2.1f,180,"Carved_Lion_Spring_Fountain",true);Stone(fountain);var rocks=Lib("SM_Cliff_Small_01_B");for(int i=0;i<21;i++){float a=i*Mathf.PI*2/21;var p=G(83+Mathf.Cos(a)*3.5f,83.3f+Mathf.Sin(a)*2.8f,-.13f);var g=Put(rocks,group,p,R(.95f,1.5f),R(0,360),"Spring_Moss_Rim_"+i);var b=B(g);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(1,.55f/Mathf.Max(.1f,b.size.y),.8f));}
var water=new GameObject("Irregular_Spring_Water");water.transform.SetParent(group,false);var mesh=new Mesh();var vv=new Vector3[50];var uv=new Vector2[50];var tt=new int[48*3];var center=G(83,83.3f,.28f);vv[0]=center;uv[0]=new Vector2(.5f,.5f);for(int i=0;i<=48;i++){float a=i*Mathf.PI*2/48;float rad=1+.04f*Mathf.Sin(i*2.3f);vv[i+1]=center+new Vector3(Mathf.Cos(a)*3.1f*rad,0,Mathf.Sin(a)*2.4f*rad);uv[i+1]=new Vector2(.5f+Mathf.Cos(a)*.5f,.5f+Mathf.Sin(a)*.5f);if(i<48){tt[i*3]=0;tt[i*3+1]=i+2;tt[i*3+2]=i+1;}}mesh.vertices=vv;mesh.uv=uv;mesh.triangles=tt;mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/SpringWater.mesh");water.AddComponent<MeshFilter>().sharedMesh=mesh;var mr=water.AddComponent<MeshRenderer>();var oldWater=old.First(t=>t.name=="Spring_Inset_Basin_Water").GetComponent<Renderer>();mr.sharedMaterial=oldWater.sharedMaterial;
var altar=Put(Lib("TFD_Altar_02A"),group,G(77,86),1.8f,18,"Engraved_Offering_Altar",true);Stone(altar);var lily=Lib("TFD_Water_Lily_02A");for(int i=0;i<5;i++){Put(lily,group,center+new Vector3(R(-2,2),.035f,R(-1.5f,1.5f)),R(.4f,.7f),R(0,360),"Spring_Water_Lily_"+i);}changes.Add("Removed block spring mesh; installed carved lion fountain, irregular water, 21 moss rocks, engraved altar, water lilies.");}
static void Details(Transform[] old){var group=Group("04_Overgrown_Ruin_Details");var fern=Lib("P_fwOF_Fern_02");var rubble=Lib("P_FW01_Debris_Rubble_Small_01");foreach(var p in new[]{new Vector2(72,72),new Vector2(89,73),new Vector2(91,86),new Vector2(75,89),new Vector2(22,45),new Vector2(29,49),new Vector2(51,64),new Vector2(67,68)}){Put(rubble,group,G(p.x,p.y),R(1,1.8f),R(0,360),"Collapsed_Masonry");for(int i=0;i<3;i++)Put(fern,group,G(p.x+R(-1,1),p.y+R(-1,1)),R(.6f,1.2f),R(0,360),"Ruin_Foot_Fern");}var vine=Lib("TFD_Wall_Vine_01A");foreach(var t in old.Where(t=>t.gameObject.activeInHierarchy&&(t.name.StartsWith("Wall_")||t.name=="Detailed_Ruin_Gate")).Take(18)){var b=B(t.gameObject);Put(vine,group,new Vector3(b.center.x,b.min.y+.15f,b.min.z-.04f),Mathf.Min(1.3f,b.size.x),0,"Trailing_Ruin_Vine");}changes.Add("Added fern groups, collapsed masonry, wall vines around ruins and bridge.");}
